out={'schema':'marici.voevodsky.CR1A1a1i1a1a2i1a1a1-expanded-chamber-occurrence-signs.v1','prospective_action':'CR1A1a1i1a1a2i1a1a1_derive_expanded_chamber_occurrence_signs','outcome_contract':{'++':'ordered incidence determines an integral signed cellular map on every expanded chamber','+-':'signs exist but some mixed filler remains nonintegral or ambiguous','-+':'the signed cellular chain equation fails','--':'expanded incidence is unavailable'},'resolution':'++','source_complex':{'ranks':[18,24,8],'d1_rank':17,'d2_rank':7,'d2_Smith_units':7,'inserted_vertices':12},'target_complex':{'ranks':[14,21,9],'d2_rank':8,'d2_Smith_units':8},'map':{'chain_equation':True,'same_sheet_zero_fillers':2,'mixed_fillers':6,'facets_per_mixed_filler':3,'homogeneous_map_module':'Z^8','oriented_degree_absolute_value':2},'established':'The occurrence signs are forced by cellular orientation and produce an integral chain map across all expanded chambers.','withheld':'Finite cellular realization does not yet supply the proper extraordinary kernel or maximal-cone six-functor Beck-Chevalley comparison.','next':'CR1A1a1i1a1a2i1a1a2_construct_maximal_cone_BC_maps','checks':checks,'passed':True};p=ROOT/'research/voevodsky/results/CR1A1a1i1a1a2i1a1a1_expanded_chamber_occurrence_signs.json';p.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({'passed':True,'resolution':'++','mixed_fillers':6,'chain_equation':True,'next':out['next']}))
